+}
+
+const MOCK_FIT_BREAKDOWN: FitBreakdown = {
+  fitPercent: 72,
+  totalWeight: 100,
+  partCargo: false,
+  vesselClass: 'handymax',
+  sanctionsPenalty: 0,
+  chartererPenalty: 0,
+  appliedCap: null,
+  components: [
+    { factor: 'timing', label: 'Timing', weight: 25, score: 20, rationale: 'ideal' },
+    { factor: 'utilisation', label: 'DWT utilisation', weight: 20, score: 15, rationale: 'good utilisation' },
+    { factor: 'economics', label: 'Economics', weight: 15, score: 12, rationale: 'positive TCE' },
+    { factor: 'ballast', label: 'Ballast', weight: 10, score: 8, rationale: 'short reposition' },
+    { factor: 'classFit', label: 'Class fit', weight: 10, score: 8, rationale: 'handymax match' },
+    { factor: 'cargoType', label: 'Cargo type', weight: 10, score: 9, rationale: 'compatible' },
+  ],
+  inputs: {
+    distanceNm: 11000,
+    gapDays: 2,
