+
+    // ── Path A: computeAndPersistMatches (mocked analyzePairs) ──────────────
+    const dbA = freshDb();
+    (analyzePairs as jest.Mock).mockResolvedValueOnce({
+      matches: [matchObj],
+      lowConfidenceMatches: [],
+      insufficientData: [],
+      blockedMatches: [],
+    });
+    await computeAndPersistMatches([cargo], [vessel], 'session-A', dbA);
+    const rowsA = listMatches(dbA, { sortBy: 'score', sortDir: 'desc', user_id: 'session-A' });
+    expect(rowsA).toHaveLength(1);
+    const rowA = rowsA[0];
+
+    // ── Path B: persistSessionMatches (direct Match[]) ───────────────────────
+    const dbB = freshDb();
+    persistSessionMatches(dbB, 'session-B', [matchObj], [cargo], [vessel]);
+    const rowsB = listMatches(dbB, { sortBy: 'score', sortDir: 'desc', user_id: 'session-B' });
+    expect(rowsB).toHaveLength(1);
+    const rowB = rowsB[0];
