+      expect({ path: 'A', col, populated: rowA[col] != null }).toEqual({ path: 'A', col, populated: true });
+      expect({ path: 'B', col, populated: rowB[col] != null }).toEqual({ path: 'B', col, populated: true });
+    }
+
+    // 21st column: reason_structured must be null in both (B.1 fix)
+    expect(rowA.reason_structured).toBeNull();
+    expect(rowB.reason_structured).toBeNull();
+
+    // ── Deterministic columns must be equal ───────────────────────────────────
+    expect(rowA.cargo_item_index).toBe(rowB.cargo_item_index);
+    expect(rowA.vessel_item_index).toBe(rowB.vessel_item_index);
+    expect(rowA.breakeven_tce_usd_per_day).toBe(rowB.breakeven_tce_usd_per_day);
+    expect(rowA.cargo_type).toBe(rowB.cargo_type);
+    expect(rowA.load_port).toBe(rowB.load_port);
+    expect(rowA.discharge_port).toBe(rowB.discharge_port);
+    expect(rowA.vessel_name).toBe(rowB.vessel_name);
+    expect(rowA.cargo_ref).toBe(rowB.cargo_ref);
+    expect(rowA.distance_nm).toBe(rowB.distance_nm);
+    expect(rowA.vessel_dwt).toBe(rowB.vessel_dwt);
+    expect(rowA.consumption_estimated).toBe(rowB.consumption_estimated);
+    expect(rowA.laycan_start).toBe(rowB.laycan_start);
+    expect(rowA.laycan_end).toBe(rowB.laycan_end);
+  });
+
+  it('refreshComputed updates stale economics without changing status or created_at', () => {
+    const cargo = makeCargo();
+    const vessel = makeVessel();
+    const matchObj = makeFullMatch();
+    const db = freshDb();
+
+    // First write (creates the row)
+    persistSessionMatches(db, 'session-R', [matchObj], [cargo], [vessel]);
+    const [first] = listMatches(db, { sortBy: 'score', sortDir: 'desc', user_id: 'session-R' });
+    expect(first.tce_usd_per_day).not.toBeNull();
+    const originalCreatedAt = first.created_at;
+    const originalStatus = first.status;
+
+    // Second write (row already exists — refreshComputed updates economics)
+    persistSessionMatches(db, 'session-R', [matchObj], [cargo], [vessel]);
+    const [refreshed] = listMatches(db, { sortBy: 'score', sortDir: 'desc', user_id: 'session-R' });
+
+    // Exactly one row — no duplicates
+    expect(listMatches(db, { sortBy: 'score', sortDir: 'desc', user_id: 'session-R' })).toHaveLength(1);
+
+    // Immutable metadata
+    expect(refreshed.created_at).toBe(originalCreatedAt);
+    expect(refreshed.status).toBe(originalStatus);
+
+    // Economics columns still populated after refresh
+    expect(refreshed.tce_usd_per_day).not.toBeNull();
+    expect(refreshed.fit_percent).not.toBeNull();
+    expect(refreshed.worksheet_json).not.toBeNull();
+    expect(refreshed.breakeven_tce_usd_per_day).not.toBeNull();
+  });
+});
