+  let computeRow: ReturnType<typeof listMatches>[number];
+  let persistRow: ReturnType<typeof listMatches>[number];
+
+  beforeAll(async () => {
+    const db = freshDb();
+
+    // Background precompute path
+    (analyzePairs as jest.Mock).mockResolvedValueOnce({
+      matches: [match],
+      lowConfidenceMatches: [],
+      insufficientData: [],
+      blockedMatches: [],
+    });
+    await computeAndPersistMatches([demoCargo], [demoVessel], 'session-compute', db);
+
+    // Detail-page path (different session so UNIQUE constraint doesn't collide)
+    persistSessionMatches(db, 'session-persist', [match], [demoCargo], [demoVessel]);
+
+    const rows = listMatches(db, { sortBy: 'score', sortDir: 'desc' });
+    computeRow = rows.find((r) => r.user_id === 'session-compute')!;
+    persistRow  = rows.find((r) => r.user_id === 'session-persist')!;
+  });
+
+  it('both rows are written', () => {
+    expect(computeRow).toBeDefined();
+    expect(persistRow).toBeDefined();
+  });
+
+  // ── columns 1–6: route / timing ───────────────────────────────────────────
+  it('cargo_type matches',      () => expect(computeRow.cargo_type).toBe(persistRow.cargo_type));
+  it('load_port matches',       () => expect(computeRow.load_port).toBe(persistRow.load_port));
+  it('discharge_port matches',  () => expect(computeRow.discharge_port).toBe(persistRow.discharge_port));
+  it('laycan_start matches',    () => expect(computeRow.laycan_start).toBe(persistRow.laycan_start));
+  it('laycan_end matches',      () => expect(computeRow.laycan_end).toBe(persistRow.laycan_end));
+  it('vessel_dwt matches',      () => expect(computeRow.vessel_dwt).toBe(persistRow.vessel_dwt));
+
+  // ── columns 7–10: economics ───────────────────────────────────────────────
+  it('tce_usd_per_day matches',         () => expect(computeRow.tce_usd_per_day).toBe(persistRow.tce_usd_per_day));
+  it('distance_nm matches',             () => expect(computeRow.distance_nm).toBe(persistRow.distance_nm));
+  it('freight_rate_usd_per_mt matches', () => expect(computeRow.freight_rate_usd_per_mt).toBe(persistRow.freight_rate_usd_per_mt));
+  it('freight_rate_source matches',     () => expect(computeRow.freight_rate_source).toBe(persistRow.freight_rate_source));
+
+  // ── columns 11–12: identity ───────────────────────────────────────────────
+  it('vessel_name matches', () => expect(computeRow.vessel_name).toBe(persistRow.vessel_name));
+  it('cargo_ref matches',   () => expect(computeRow.cargo_ref).toBe(persistRow.cargo_ref));
+
+  // ── columns 13–14: fit ────────────────────────────────────────────────────
+  it('fit_percent is non-null and matches', () => {
+    expect(computeRow.fit_percent).not.toBeNull();
+    expect(computeRow.fit_percent).toBeCloseTo(persistRow.fit_percent!);
+  });
+  it('fit_breakdown component count matches', () => {
+    expect(computeRow.fit_breakdown).not.toBeNull();
+    const c = JSON.parse(computeRow.fit_breakdown!);
+    const p = JSON.parse(persistRow.fit_breakdown!);
+    expect(c.components).toHaveLength(p.components.length);
+  });
+
+  // ── columns 15–16: item indices ───────────────────────────────────────────
+  it('cargo_item_index matches',  () => expect(computeRow.cargo_item_index).toBe(persistRow.cargo_item_index));
+  it('vessel_item_index matches', () => expect(computeRow.vessel_item_index).toBe(persistRow.vessel_item_index));
+
+  // ── column 17: worksheet ─────────────────────────────────────────────────
+  it('worksheet_json readiness.verdict matches', () => {
+    expect(computeRow.worksheet_json).not.toBeNull();
+    const cw = JSON.parse(computeRow.worksheet_json!);
+    const pw = JSON.parse(persistRow.worksheet_json!);
+    expect(cw.readiness.verdict).toBe(pw.readiness.verdict);
+  });
+
+  // ── columns 18–19: consumption / ballast ─────────────────────────────────
+  it('consumption_estimated matches', () => expect(computeRow.consumption_estimated).toBe(persistRow.consumption_estimated));
+  it('ballast_distance_nm matches',   () => expect(computeRow.ballast_distance_nm).toBe(persistRow.ballast_distance_nm));
+
+  // ── column 20: breakeven ─────────────────────────────────────────────────
+  it('breakeven_tce_usd_per_day is non-null and matches', () => {
+    expect(computeRow.breakeven_tce_usd_per_day).not.toBeNull();
+    expect(computeRow.breakeven_tce_usd_per_day).toBe(persistRow.breakeven_tce_usd_per_day);
+  });
+
+  // ── column 21: reason_structured ─────────────────────────────────────────
+  it('reason_structured matches', () => {
+    // Both paths write m.scoreBreakdown as JSON (or null when absent)
+    expect(computeRow.reason_structured).toBe(persistRow.reason_structured);
+  });
+});
