+/**
+ * Write-path parity — computeAndPersistMatches vs persistSessionMatches
+ *
+ * Both write paths must store the same 21 non-metadata columns so a match
+ * renders identically regardless of which path saved it (B.2 regression guard).
+ *
+ * The 21 columns checked:
+ *   cargo_type, load_port, discharge_port, laycan_start, laycan_end, vessel_dwt,
+ *   tce_usd_per_day, distance_nm, freight_rate_usd_per_mt, freight_rate_source,
+ *   vessel_name, cargo_ref, fit_percent, fit_breakdown, cargo_item_index,
+ *   vessel_item_index, worksheet_json, consumption_estimated, ballast_distance_nm,
+ *   breakeven_tce_usd_per_day, reason_structured (null in both after B.1 fix).
+ *
+ * analyzePairs is mocked; both paths call computeStoredMatchEconomics for real
+ * (deterministic given same ports).
+ */
+
+import Database from 'better-sqlite3';
+import { runMigrations } from '@/lib/migrations/runner';
+import { allMigrations } from '@/lib/migrations/index';
+import { computeAndPersistMatches } from '@/lib/matching/compute-matches';
+import { persistSessionMatches } from '@/lib/matching/persist-session-matches';
+import { listMatches } from '@/lib/matching/matches-repository';
+import type { ParsedCargo, ParsedVessel, Match, FitBreakdown, MatchWorksheet } from '@/lib/types';
+
+jest.mock('@/lib/matching/pair-analyzer', () => ({
+  analyzePairs: jest.fn(),
+  IDLE_HARD_MAX_GAP_DAYS: 21,
+}));
+
+import { analyzePairs } from '@/lib/matching/pair-analyzer';
+
+const CARGO_EMAIL_ID = 'parity-cargo-1';
+const VESSEL_EMAIL_ID = 'parity-vessel-1';
+
+function freshDb(): Database.Database {
+  const db = new Database(':memory:');
+  runMigrations(db, allMigrations);
+  return db;
+}
+
+function makeCargo(): ParsedCargo {
+  return {
+    emailId: CARGO_EMAIL_ID,
+    itemIndex: 0,
+    originPort: { value: 'Rotterdam', confidence: 'confirmed' },
+    originCountry: 'NL',
+    destinationPort: { value: 'Singapore', confidence: 'confirmed' },
+    destinationCountry: 'SG',
+    cargoType: 'grain',
+    cargoDescription: { value: '37 440 mt grain', confidence: 'confirmed' },
+    laycan: '1-10 Aug 2026',
+    weightMt: { value: 37440, confidence: 'confirmed' },
+    weightMtMin: null,
+    weightMtMax: null,
+    volumeCbm: null,
+    dimensions: null,
+    containerType: null,
+    quantity: null,
+    incoterms: null,
+    preferredDates: null,
+    loadingRate: null,
+    dischargeRate: null,
+    commissionPercent: null,
+    commissionTerms: null,
+    specialRequirements: null,
+    stowageFactor: null,
+    missingInfo: [],
+  };
+}
+
+function makeVessel(): ParsedVessel {
+  return {
+    emailId: VESSEL_EMAIL_ID,
+    itemIndex: 0,
+    vesselName: { value: 'SEAGULL 200', confidence: 'confirmed' },
+    dwtSummer: { value: 52000, confidence: 'confirmed' },
+    openDate: { value: '2026-07-15', confidence: 'confirmed' },
+    openPosition: { value: 'Rotterdam', confidence: 'confirmed' },
+    speedLaden: '13 kts',
+    // consumption: null triggers consumption_estimated = 1 (class-aware fallback)
+    consumption: null,
+    vesselType: 'bulk',
+    imo: null,
+    flag: 'MH',
+    built: 2018,
+    classSociety: 'BV',
+    pandi: null,
+    dwcc: { value: 51000, confidence: 'confirmed' },
+    draftMax: { value: 11, confidence: 'confirmed' },
+    loa: null,
+    beam: null,
+    grt: null,
+    nrt: null,
+    holdsCount: null,
+    hatchesCount: null,
+    grainCapacity: null,
+    grainCapacityUnit: null,
+    baleCapacity: null,
+    holdDimensions: null,
+    hatchDimensions: null,
+    tankTopStrength: null,
+    geared: false,
+    craneCapacity: null,
+    hatchType: null,
+    direction: null,
+    restrictions: [],
+    lastCargoes: null,
+    speedBallast: null,
+    deckCapacity: null,
+    specialFeatures: [],
+  };
+}
+
+const MOCK_FIT_BREAKDOWN: FitBreakdown = {
+  fitPercent: 72,
+  totalWeight: 100,
+  partCargo: false,
+  vesselClass: 'handymax',
+  sanctionsPenalty: 0,
+  chartererPenalty: 0,
+  appliedCap: null,
+  components: [
+    { factor: 'timing', label: 'Timing', weight: 25, score: 20, rationale: 'ideal' },
+    { factor: 'utilisation', label: 'DWT utilisation', weight: 20, score: 15, rationale: 'good utilisation' },
+    { factor: 'economics', label: 'Economics', weight: 15, score: 12, rationale: 'positive TCE' },
+    { factor: 'ballast', label: 'Ballast', weight: 10, score: 8, rationale: 'short reposition' },
+    { factor: 'classFit', label: 'Class fit', weight: 10, score: 8, rationale: 'handymax match' },
+    { factor: 'cargoType', label: 'Cargo type', weight: 10, score: 9, rationale: 'compatible' },
+  ],
+  inputs: {
+    distanceNm: 11000,
+    gapDays: 2,
+    verdict: 'ideal',
+    utilisation: 0.72,
+    vesselDwt: 52000,
+    cargoWtMax: 37440,
+  },
+};
+
+const MOCK_WORKSHEET: MatchWorksheet = {
+  readiness: {
+    openDate: '2026-07-15',
+    laycanStart: '2026-08-01',
+    laycanEnd: '2026-08-10',
+    distanceNm: 11000,
+    distanceExact: true,
+    speedKn: 13,
+    sailingDays: 35.3,
+    arrivalDate: '2026-07-30',
+    gapDays: 2,
+    verdict: 'ideal',
+    explanation: 'ideal: vessel arrives 2 days early',
+    openPosition: 'Rotterdam',
+  },
+  vessel: {
+    draftMax: 11,
+    grainCapacity: null,
+    grainCapacityUnit: null,
+    geared: false,
+    vesselType: 'bulk',
+    flag: 'MH',
+    built: 2018,
+    pandi: null,
+    classSociety: 'BV',
+    lastCargoes: null,
+    dwtSummer: 52000,
+    dwcc: 51000,
+  },
+  cargo: {
+    weightMt: 37440,
+    weightMtEffective: 37440,
+    cargoType: 'grain',
+    loadPort: 'Rotterdam',
+    dischargePort: 'Singapore',
+  },
+  hardFilters: { draft: 'pass', crane: 'pass', volume: 'pass' },
+  sanctions: { blocking: false, flags: [] },
+};
+
+function makeFullMatch(): Match {
+  return {
+    cargoEmailId: CARGO_EMAIL_ID,
+    cargoItemIndex: 0,
+    vesselEmailId: VESSEL_EMAIL_ID,
+    vesselItemIndex: 0,
+    score: 78,
+    matchLevel: 'good',
+    matchReasons: ['DWT fits cargo weight'],
+    issues: [],
+    fitPercent: MOCK_FIT_BREAKDOWN.fitPercent,
+    fitBreakdown: MOCK_FIT_BREAKDOWN,
+    worksheet: MOCK_WORKSHEET,
+    hardFilters: { draft: 'pass', crane: 'pass', volume: 'pass' },
+    sanctions: { blocking: false, flags: [] },
+    scoreBreakdown: undefined,
+  };
+}
+
+// 21 columns both write paths must populate identically.
+// MUST_BE_POPULATED: non-null given the fixture (19 columns).
+// Plus reason_structured (null in both after B.1) and consumption_estimated
+// (1 in both since vessel.consumption is null → class-aware fallback).
+const MUST_BE_POPULATED = [
+  'cargo_type', 'load_port', 'discharge_port',
+  'laycan_start', 'laycan_end', 'vessel_dwt',
+  'tce_usd_per_day', 'distance_nm',
+  'freight_rate_usd_per_mt', 'freight_rate_source',
+  'vessel_name', 'cargo_ref',
+  'fit_percent', 'fit_breakdown',
+  'cargo_item_index', 'vessel_item_index',
+  'worksheet_json',
+  'consumption_estimated',
+  'ballast_distance_nm',
+  'breakeven_tce_usd_per_day',
+] as const; // 20 of the 21 columns
+
+beforeEach(() => {
+  jest.clearAllMocks();
+});
+
+describe('write-path parity — 21 columns', () => {
+  it('both paths populate all 20 non-null columns and agree on reason_structured (null)', async () => {
+    const cargo = makeCargo();
+    const vessel = makeVessel();
+    const matchObj = makeFullMatch();
+
+    // ── Path A: computeAndPersistMatches (mocked analyzePairs) ──────────────
+    const dbA = freshDb();
+    (analyzePairs as jest.Mock).mockResolvedValueOnce({
+      matches: [matchObj],
+      lowConfidenceMatches: [],
+      insufficientData: [],
+      blockedMatches: [],
+    });
+    await computeAndPersistMatches([cargo], [vessel], 'session-A', dbA);
+    const rowsA = listMatches(dbA, { sortBy: 'score', sortDir: 'desc', user_id: 'session-A' });
+    expect(rowsA).toHaveLength(1);
+    const rowA = rowsA[0];
+
+    // ── Path B: persistSessionMatches (direct Match[]) ───────────────────────
+    const dbB = freshDb();
+    persistSessionMatches(dbB, 'session-B', [matchObj], [cargo], [vessel]);
+    const rowsB = listMatches(dbB, { sortBy: 'score', sortDir: 'desc', user_id: 'session-B' });
+    expect(rowsB).toHaveLength(1);
+    const rowB = rowsB[0];
+
+    // ── All 20 non-null columns must be populated in both paths ───────────────
+    for (const col of MUST_BE_POPULATED) {
+      expect({ path: 'A', col, populated: rowA[col] != null }).toEqual({ path: 'A', col, populated: true });
+      expect({ path: 'B', col, populated: rowB[col] != null }).toEqual({ path: 'B', col, populated: true });
+    }
+
+    // 21st column: reason_structured must be null in both (B.1 fix)
+    expect(rowA.reason_structured).toBeNull();
+    expect(rowB.reason_structured).toBeNull();
+
+    // ── Deterministic columns must be equal ───────────────────────────────────
+    expect(rowA.cargo_item_index).toBe(rowB.cargo_item_index);
+    expect(rowA.vessel_item_index).toBe(rowB.vessel_item_index);
+    expect(rowA.breakeven_tce_usd_per_day).toBe(rowB.breakeven_tce_usd_per_day);
+    expect(rowA.cargo_type).toBe(rowB.cargo_type);
+    expect(rowA.load_port).toBe(rowB.load_port);
+    expect(rowA.discharge_port).toBe(rowB.discharge_port);
+    expect(rowA.vessel_name).toBe(rowB.vessel_name);
+    expect(rowA.cargo_ref).toBe(rowB.cargo_ref);
+    expect(rowA.distance_nm).toBe(rowB.distance_nm);
+    expect(rowA.vessel_dwt).toBe(rowB.vessel_dwt);
+    expect(rowA.consumption_estimated).toBe(rowB.consumption_estimated);
+    expect(rowA.laycan_start).toBe(rowB.laycan_start);
+    expect(rowA.laycan_end).toBe(rowB.laycan_end);
+  });
+
+  it('refreshComputed updates stale economics without changing status or created_at', () => {
+    const cargo = makeCargo();
+    const vessel = makeVessel();
+    const matchObj = makeFullMatch();
+    const db = freshDb();
+
+    // First write (creates the row)
+    persistSessionMatches(db, 'session-R', [matchObj], [cargo], [vessel]);
+    const [first] = listMatches(db, { sortBy: 'score', sortDir: 'desc', user_id: 'session-R' });
+    expect(first.tce_usd_per_day).not.toBeNull();
+    const originalCreatedAt = first.created_at;
+    const originalStatus = first.status;
+
+    // Second write (row already exists — refreshComputed updates economics)
+    persistSessionMatches(db, 'session-R', [matchObj], [cargo], [vessel]);
+    const [refreshed] = listMatches(db, { sortBy: 'score', sortDir: 'desc', user_id: 'session-R' });
+
+    // Exactly one row — no duplicates
+    expect(listMatches(db, { sortBy: 'score', sortDir: 'desc', user_id: 'session-R' })).toHaveLength(1);
+
+    // Immutable metadata
+    expect(refreshed.created_at).toBe(originalCreatedAt);
+    expect(refreshed.status).toBe(originalStatus);
+
+    // Economics columns still populated after refresh
+    expect(refreshed.tce_usd_per_day).not.toBeNull();
+    expect(refreshed.fit_percent).not.toBeNull();
+    expect(refreshed.worksheet_json).not.toBeNull();
+    expect(refreshed.breakeven_tce_usd_per_day).not.toBeNull();
+  });
+});
